from pathlib import Path
import json,re

task='DEV-PRED-PROD-STAGED-DIFF-INSPECT-20261005'
cands=[
    Path.home()/'.local/state/prediction-project-executor'/f'{task}.json',
    Path.home()/'.local/state/prediction-project-executor'/task/'RESULT.json',
    Path.home()/'prediction_research_prod'/'control/results'/task/'RESULT.json',
    Path.home()/'prediction_research_prod'/'control/results'/task/'stdout.log',
    Path.home()/'prediction_research_prod'/'control/results'/task/'stderr.log',
]
blobs=[]
for p in cands:
    if p.is_file():
        try:
            blobs.append(p.read_text(encoding='utf-8',errors='replace'))
        except Exception:
            pass
text='\n'.join(blobs)
payload=None
for m in re.finditer(r'PRODUCTION_DIFF_INSPECT\s+(\{.*?\})(?:\n|$)', text):
    raw=m.group(1)
    try:
        payload=json.loads(raw)
    except Exception:
        continue
if payload is None:
    # Some executor state JSON nests operation outputs as strings.
    try:
        root=json.loads(text)
        stack=[root]
        while stack and payload is None:
            cur=stack.pop()
            if isinstance(cur,dict):
                stack.extend(cur.values())
            elif isinstance(cur,list):
                stack.extend(cur)
            elif isinstance(cur,str) and cur.startswith('PRODUCTION_DIFF_INSPECT '):
                try: payload=json.loads(cur.split(' ',1)[1])
                except Exception: pass
    except Exception:
        pass
if payload is None:
    print('STAGED_DIFF_SUMMARY=NOT_FOUND',flush=True)
    raise SystemExit(41)

diff=payload.get('diff','')
files=[]
cur=None
stats={}
for line in diff.splitlines():
    if line.startswith('diff --git a/'):
        cur=line.split(' b/',1)[-1]
        files.append(cur)
        stats[cur]={'add':0,'del':0,'signals':[]}
        continue
    if cur is None:
        continue
    if line.startswith('+') and not line.startswith('+++'):
        stats[cur]['add']+=1
        s=line[1:].strip()
        if re.search(r'^(def |class |async def |[A-Z][A-Z0-9_]{2,}\s*=|if __name__|\w+[\w.]*\s*=)',s):
            if len(stats[cur]['signals'])<8: stats[cur]['signals'].append('+'+s[:140])
    elif line.startswith('-') and not line.startswith('---'):
        stats[cur]['del']+=1
        s=line[1:].strip()
        if re.search(r'^(def |class |async def |[A-Z][A-Z0-9_]{2,}\s*=|if __name__|\w+[\w.]*\s*=)',s):
            if len(stats[cur]['signals'])<8: stats[cur]['signals'].append('-'+s[:140])

parts=[]
for f in files:
    st=stats[f]
    sig=';'.join(st['signals'][:4])
    parts.append(f"{f}[+{st['add']}/-{st['del']}]"+(f"{{{sig}}}" if sig else ""))
summary=' | '.join(parts)
print('STAGED_DIFF_SUMMARY='+summary[:7000],flush=True)
raise SystemExit(42)
